export const mrs: MergeRequest[] = Array.from({ length: 10 }, (_, i) => ({
	id: i + 1,
	project: i % 2 ? "beta" : "alpha",
	title: `Synthetic change ${i + 1}`,
	ref: `demo!${i + 1}`,
	author: "Example",
	source_branch: "work",
	target_branch: "main",
	keys: [`TEST-${i + 1}`],
	status: i % 2 ? "done" : "ready",
	status_via: "state",
	updated_at: "2026-01-02T00:00:00Z",
	url: `https://example.invalid/mr/${i + 1}`,
}));
